from pathlib import Path

def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected 1 match, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

Path("platform_core/training_bundle_cache.py").write_text('from __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nimport shutil\nimport stat\nimport uuid\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom pathlib import Path, PureWindowsPath\nfrom typing import Any, Callable, Mapping\n\nfrom filelock import FileLock\n\n\nCACHE_SCHEMA_VERSION = 1\n_CACHE_ROOT_NAME = "training-bundles"\n\n\ndef _sha256(path: Path) -> str:\n    digest = hashlib.sha256()\n    with path.open("rb") as stream:\n        for chunk in iter(lambda: stream.read(1024 * 1024), b""):\n            digest.update(chunk)\n    return digest.hexdigest()\n\n\ndef _safe_component(value: str, *, label: str) -> str:\n    text = str(value or "")\n    windows = PureWindowsPath(text)\n    if (\n        not text\n        or text in {".", ".."}\n        or "/" in text\n        or "\\\\" in text\n        or windows.drive\n        or windows.root\n    ):\n        raise ValueError(f"{label} must be one safe path component")\n    return text\n\n\ndef _snapshot_id(value: str) -> str:\n    text = str(value or "").strip().lower()\n    if len(text) != 64 or any(ch not in "0123456789abcdef" for ch in text):\n        raise ValueError("snapshot_id must be a lowercase SHA256 hex digest")\n    return text\n\n\ndef _path_info(path: Path) -> os.stat_result | None:\n    try:\n        return path.lstat()\n    except FileNotFoundError:\n        return None\n\n\ndef _is_link_like(path: Path) -> bool:\n    info = _path_info(path)\n    if info is None:\n        return False\n    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)\n    return stat.S_ISLNK(info.st_mode) or bool(\n        getattr(info, "st_file_attributes", 0) & reparse_flag\n    )\n\n\ndef _has_link_component(root: Path, path: Path) -> bool:\n    base = root.resolve()\n    try:\n        relative = path.resolve().relative_to(base)\n    except ValueError:\n        return True\n    current = base\n    for part in relative.parts:\n        current = current / part\n        if _is_link_like(current):\n            return True\n    return False\n\n\ndef _portable_relative(reference: str) -> Path:\n    raw = str(reference or "")\n    value = Path(raw)\n    windows = PureWindowsPath(raw)\n    if (\n        not raw\n        or "\\\\" in raw\n        or value.is_absolute()\n        or windows.is_absolute()\n        or windows.drive\n        or windows.root\n        or ".." in value.parts\n        or ".." in windows.parts\n    ):\n        raise ValueError("relative portable bundle reference required")\n    return value\n\n\ndef _resolve_relative(root: Path, reference: str) -> Path:\n    relative = _portable_relative(reference)\n    base = root.resolve()\n    resolved = (base / relative).resolve()\n    if resolved != base and base not in resolved.parents:\n        raise ValueError("relative portable bundle reference required")\n    return resolved\n\n\ndef _real_directory(path: Path, *, label: str) -> Path:\n    resolved = path.resolve()\n    info = _path_info(resolved)\n    if info is None or _is_link_like(resolved) or not stat.S_ISDIR(info.st_mode):\n        raise ValueError(f"{label} must be a real directory")\n    return resolved\n\n\ndef _safe_rmtree(path: Path, *, parent: Path) -> None:\n    if not path.exists():\n        return\n    resolved_parent = parent.resolve()\n    resolved = path.resolve()\n    if resolved.parent != resolved_parent:\n        raise ValueError("cache cleanup escaped its parent")\n    info = _path_info(path)\n    if info is None:\n        return\n    if _is_link_like(path) or not stat.S_ISDIR(info.st_mode):\n        raise ValueError("cache cleanup target must be a real directory")\n    shutil.rmtree(path)\n\n\n@dataclass(frozen=True)\nclass TrainingBundleCacheEntry:\n    root: Path\n    bundle: Path\n    snapshot_id: str\n    verified_files: int\n    manifest_sha256: str\n\n\nclass TrainingBundleCache:\n    """Project-scoped immutable cache for fully verified portable training bundles."""\n\n    def __init__(self, data_dir: str | Path, project_id: str) -> None:\n        self.data_dir = Path(data_dir).resolve()\n        self.project_id = _safe_component(project_id, label="project_id")\n        self.root = self.data_dir / "cache" / _CACHE_ROOT_NAME / self.project_id\n\n    def _entry_root(self, snapshot_id: str) -> Path:\n        return self.root / _snapshot_id(snapshot_id)\n\n    def _lock(self, snapshot_id: str) -> FileLock:\n        self.root.mkdir(parents=True, exist_ok=True)\n        return FileLock(str(self.root / f".{_snapshot_id(snapshot_id)}.lock"), timeout=300)\n\n    def _resolve_unlocked(self, snapshot_id: str) -> TrainingBundleCacheEntry | None:\n        sid = _snapshot_id(snapshot_id)\n        entry_root = self._entry_root(sid)\n        info = _path_info(entry_root)\n        if info is None or _is_link_like(entry_root) or not stat.S_ISDIR(info.st_mode):\n            return None\n        marker_path = entry_root / "cache.json"\n        bundle = entry_root / "bundle"\n        manifest_path = bundle / "manifest.json"\n        for candidate in (marker_path, bundle, manifest_path):\n            if _is_link_like(candidate):\n                return None\n        try:\n            marker = json.loads(marker_path.read_text(encoding="utf-8"))\n            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))\n        except (OSError, json.JSONDecodeError):\n            return None\n        if (\n            int(marker.get("schema_version") or 0) != CACHE_SCHEMA_VERSION\n            or str(marker.get("snapshot_id") or "") != sid\n            or str(manifest.get("snapshot_id") or "") != sid\n        ):\n            return None\n        expected_manifest_sha = str(marker.get("manifest_sha256") or "")\n        if not expected_manifest_sha or _sha256(manifest_path) != expected_manifest_sha:\n            return None\n\n        try:\n            snapshot_path = _resolve_relative(\n                bundle, str(manifest.get("snapshot_ref") or "")\n            )\n            data_yaml = _resolve_relative(\n                bundle, str(manifest.get("data_yaml_ref") or "")\n            )\n        except ValueError:\n            return None\n        expected_snapshot_sha = str(manifest.get("snapshot_sha256") or "")\n        if (\n            _has_link_component(bundle, snapshot_path)\n            or not snapshot_path.is_file()\n            or not expected_snapshot_sha\n            or _sha256(snapshot_path) != expected_snapshot_sha\n            or _has_link_component(bundle, data_yaml)\n            or not data_yaml.is_file()\n        ):\n            return None\n\n        verified_files = 0\n        try:\n            for role in ("train", "validation", "test"):\n                for member in (manifest.get("splits") or {}).get(role, []):\n                    image_path = _resolve_relative(\n                        bundle, str(member.get("image_ref") or "")\n                    )\n                    label_path = _resolve_relative(\n                        bundle, str(member.get("label_ref") or "")\n                    )\n                    expected_size = int(member.get("size_bytes") or 0)\n                    if (\n                        _has_link_component(bundle, image_path)\n                        or not image_path.is_file()\n                        or expected_size <= 0\n                        or image_path.stat().st_size != expected_size\n                        or _has_link_component(bundle, label_path)\n                        or not label_path.is_file()\n                    ):\n                        return None\n                    verified_files += 1\n        except (OSError, TypeError, ValueError):\n            return None\n        if verified_files != int(marker.get("verified_files") or -1):\n            return None\n        return TrainingBundleCacheEntry(\n            root=entry_root,\n            bundle=bundle,\n            snapshot_id=sid,\n            verified_files=verified_files,\n            manifest_sha256=expected_manifest_sha,\n        )\n\n    def resolve(self, snapshot_id: str) -> TrainingBundleCacheEntry | None:\n        with self._lock(snapshot_id):\n            return self._resolve_unlocked(snapshot_id)\n\n    @staticmethod\n    def _clone_bundle(\n        source_bundle: Path,\n        destination_bundle: Path,\n        *,\n        progress: Callable[[int, int, Mapping[str, Any]], None] | None = None,\n    ) -> dict[str, int]:\n        source = _real_directory(source_bundle, label="source bundle")\n        destination_bundle.mkdir(parents=True, exist_ok=False)\n        manifest_path = source / "manifest.json"\n        if _is_link_like(manifest_path) or not manifest_path.is_file():\n            raise ValueError("source bundle manifest is missing")\n        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))\n        members: list[Mapping[str, Any]] = []\n        for role in ("train", "validation", "test"):\n            members.extend((manifest.get("splits") or {}).get(role, []))\n\n        hardlinked_images = 0\n        copied_images = 0\n        label_files = 0\n        for index, member in enumerate(members, start=1):\n            image_ref = str(member.get("image_ref") or "")\n            label_ref = str(member.get("label_ref") or "")\n            source_image = _resolve_relative(source, image_ref)\n            source_label = _resolve_relative(source, label_ref)\n            expected_size = int(member.get("size_bytes") or 0)\n            if (\n                _has_link_component(source, source_image)\n                or not source_image.is_file()\n                or expected_size <= 0\n                or source_image.stat().st_size != expected_size\n                or _has_link_component(source, source_label)\n                or not source_label.is_file()\n            ):\n                raise ValueError(f"cache source member is invalid: {member.get(\'image_id\')}")\n            destination_image = _resolve_relative(destination_bundle, image_ref)\n            destination_label = _resolve_relative(destination_bundle, label_ref)\n            destination_image.parent.mkdir(parents=True, exist_ok=True)\n            destination_label.parent.mkdir(parents=True, exist_ok=True)\n            try:\n                os.link(source_image, destination_image)\n                hardlinked_images += 1\n            except OSError:\n                shutil.copy2(source_image, destination_image)\n                copied_images += 1\n            shutil.copy2(source_label, destination_label)\n            label_files += 1\n            if progress is not None:\n                progress(index, len(members), member)\n\n        for reference_key in ("snapshot_ref", "data_yaml_ref"):\n            reference = str(manifest.get(reference_key) or "")\n            source_path = _resolve_relative(source, reference)\n            destination_path = _resolve_relative(destination_bundle, reference)\n            if _has_link_component(source, source_path) or not source_path.is_file():\n                raise ValueError(f"cache source {reference_key} is invalid")\n            destination_path.parent.mkdir(parents=True, exist_ok=True)\n            shutil.copy2(source_path, destination_path)\n        shutil.copy2(manifest_path, destination_bundle / "manifest.json")\n        return {\n            "verified_files": len(members),\n            "hardlinked_images": hardlinked_images,\n            "copied_images": copied_images,\n            "label_files": label_files,\n        }\n\n    def restore(\n        self,\n        entry: TrainingBundleCacheEntry,\n        task_work_root: str | Path,\n        *,\n        progress: Callable[[int, int, Mapping[str, Any]], None] | None = None,\n    ) -> tuple[Path, dict[str, int]]:\n        work = Path(task_work_root).resolve()\n        if _is_link_like(work):\n            raise ValueError("training work path must not be link-like")\n        work.mkdir(parents=True, exist_ok=True)\n        with self._lock(entry.snapshot_id):\n            current = self._resolve_unlocked(entry.snapshot_id)\n            if current is None or current.manifest_sha256 != entry.manifest_sha256:\n                raise ValueError("training bundle cache entry is no longer valid")\n            temporary = work / f".bundle-cache-{uuid.uuid4().hex}.tmp"\n            target = work / "bundle"\n            try:\n                stats = self._clone_bundle(\n                    current.bundle,\n                    temporary,\n                    progress=progress,\n                )\n                if target.exists():\n                    _safe_rmtree(target, parent=work)\n                os.replace(temporary, target)\n                return target, stats\n            finally:\n                if temporary.exists():\n                    _safe_rmtree(temporary, parent=work)\n\n    def publish_verified(\n        self,\n        source_bundle: str | Path,\n        snapshot_id: str,\n        *,\n        verified_files: int,\n    ) -> tuple[TrainingBundleCacheEntry, dict[str, int | bool]]:\n        sid = _snapshot_id(snapshot_id)\n        source = _real_directory(Path(source_bundle), label="source bundle")\n        with self._lock(sid):\n            existing = self._resolve_unlocked(sid)\n            if existing is not None:\n                return existing, {\n                    "published": False,\n                    "verified_files": existing.verified_files,\n                    "hardlinked_images": 0,\n                    "copied_images": 0,\n                    "label_files": 0,\n                }\n\n            entry_root = self._entry_root(sid)\n            if entry_root.exists():\n                _safe_rmtree(entry_root, parent=self.root)\n            temporary_root = self.root / f".{sid}.{uuid.uuid4().hex}.tmp"\n            bundle = temporary_root / "bundle"\n            try:\n                temporary_root.mkdir(parents=True, exist_ok=False)\n                stats = self._clone_bundle(source, bundle)\n                if int(stats["verified_files"]) != int(verified_files):\n                    raise ValueError(\n                        "verified bundle file count does not match final validation evidence"\n                    )\n                manifest_path = bundle / "manifest.json"\n                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))\n                if str(manifest.get("snapshot_id") or "") != sid:\n                    raise ValueError("verified bundle snapshot identity mismatch")\n                marker = {\n                    "schema_version": CACHE_SCHEMA_VERSION,\n                    "snapshot_id": sid,\n                    "manifest_sha256": _sha256(manifest_path),\n                    "verified_files": int(verified_files),\n                    "published_at": datetime.now(timezone.utc).isoformat(),\n                }\n                (temporary_root / "cache.json").write_text(\n                    json.dumps(marker, ensure_ascii=False, sort_keys=True),\n                    encoding="utf-8",\n                )\n                os.replace(temporary_root, entry_root)\n            finally:\n                if temporary_root.exists():\n                    _safe_rmtree(temporary_root, parent=self.root)\n            resolved = self._resolve_unlocked(sid)\n            if resolved is None:\n                if entry_root.exists():\n                    _safe_rmtree(entry_root, parent=self.root)\n                raise ValueError("published training bundle cache failed validation")\n            return resolved, {"published": True, **stats}\n', encoding="utf-8")
Path("tests/unit/test_training_bundle_cache.py").write_text('from __future__ import annotations\n\nimport errno\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\n\nimport pytest\n\nfrom platform_core import training_bundle_cache\nfrom platform_core.training_bundle_cache import TrainingBundleCache\n\n\ndef _sha256_bytes(value: bytes) -> str:\n    return hashlib.sha256(value).hexdigest()\n\n\ndef _write_bundle(root: Path, *, snapshot_id: str) -> Path:\n    bundle = root / "bundle"\n    image_train = bundle / "dataset/images/train/img-1.jpg"\n    image_test = bundle / "dataset/images/test/img-2.jpg"\n    label_train = bundle / "dataset/labels/train/img-1.txt"\n    label_test = bundle / "evaluation/ground_truth/test/img-2.txt"\n    data_yaml = bundle / "dataset/data.yaml"\n    snapshot = bundle / "snapshot.json"\n    for path in (image_train, image_test, label_train, label_test, data_yaml, snapshot):\n        path.parent.mkdir(parents=True, exist_ok=True)\n    train_payload = b"train-image-bytes"\n    test_payload = b"test-image-bytes"\n    image_train.write_bytes(train_payload)\n    image_test.write_bytes(test_payload)\n    label_train.write_text("0 0.5 0.5 0.2 0.2", encoding="utf-8")\n    label_test.write_text("0 0.4 0.4 0.1 0.1", encoding="utf-8")\n    data_yaml.write_text("path: .\\ntrain: images/train\\nval: images/validation\\n", encoding="utf-8")\n    snapshot_payload = {"snapshot_id": snapshot_id, "schema_version": 3}\n    snapshot.write_text(json.dumps(snapshot_payload, sort_keys=True), encoding="utf-8")\n    manifest = {\n        "schema_version": 2,\n        "snapshot_id": snapshot_id,\n        "snapshot_ref": "snapshot.json",\n        "snapshot_sha256": training_bundle_cache._sha256(snapshot),\n        "data_yaml_ref": "dataset/data.yaml",\n        "splits": {\n            "train": [\n                {\n                    "image_id": "img-1",\n                    "image_ref": "dataset/images/train/img-1.jpg",\n                    "label_ref": "dataset/labels/train/img-1.txt",\n                    "content_sha256": _sha256_bytes(train_payload),\n                    "size_bytes": len(train_payload),\n                    "label_sha256": training_bundle_cache._sha256(label_train),\n                }\n            ],\n            "validation": [],\n            "test": [\n                {\n                    "image_id": "img-2",\n                    "image_ref": "dataset/images/test/img-2.jpg",\n                    "label_ref": "evaluation/ground_truth/test/img-2.txt",\n                    "content_sha256": _sha256_bytes(test_payload),\n                    "size_bytes": len(test_payload),\n                    "label_sha256": training_bundle_cache._sha256(label_test),\n                }\n            ],\n        },\n    }\n    (bundle / "manifest.json").write_text(\n        json.dumps(manifest, ensure_ascii=False, sort_keys=True),\n        encoding="utf-8",\n    )\n    return bundle\n\n\ndef test_verified_bundle_cache_publishes_and_restores_with_image_hardlinks(tmp_path):\n    snapshot_id = "a" * 64\n    source_bundle = _write_bundle(tmp_path / "source", snapshot_id=snapshot_id)\n    cache = TrainingBundleCache(tmp_path / "data", "project-a")\n\n    entry, published = cache.publish_verified(\n        source_bundle,\n        snapshot_id,\n        verified_files=2,\n    )\n    assert published["published"] is True\n    assert published["verified_files"] == 2\n\n    resolved = cache.resolve(snapshot_id)\n    assert resolved is not None\n    restored, stats = cache.restore(resolved, tmp_path / "task-work")\n\n    cache_image = entry.bundle / "dataset/images/train/img-1.jpg"\n    restored_image = restored / "dataset/images/train/img-1.jpg"\n    cache_label = entry.bundle / "dataset/labels/train/img-1.txt"\n    restored_label = restored / "dataset/labels/train/img-1.txt"\n    assert restored_image.read_bytes() == b"train-image-bytes"\n    assert stats["hardlinked_images"] == 2\n    assert stats["copied_images"] == 0\n    assert os.path.samefile(cache_image, restored_image)\n    assert not os.path.samefile(cache_label, restored_label)\n\n\ndef test_cache_resolve_rejects_missing_member_without_rehashing_images(monkeypatch, tmp_path):\n    snapshot_id = "b" * 64\n    source_bundle = _write_bundle(tmp_path / "source", snapshot_id=snapshot_id)\n    cache = TrainingBundleCache(tmp_path / "data", "project-b")\n    entry, _ = cache.publish_verified(source_bundle, snapshot_id, verified_files=2)\n\n    image = entry.bundle / "dataset/images/train/img-1.jpg"\n    image.unlink()\n\n    assert cache.resolve(snapshot_id) is None\n\n\ndef test_cache_restore_falls_back_to_copy_when_hardlink_is_unavailable(monkeypatch, tmp_path):\n    snapshot_id = "c" * 64\n    source_bundle = _write_bundle(tmp_path / "source", snapshot_id=snapshot_id)\n    cache = TrainingBundleCache(tmp_path / "data", "project-c")\n    entry, _ = cache.publish_verified(source_bundle, snapshot_id, verified_files=2)\n\n    monkeypatch.setattr(\n        training_bundle_cache.os,\n        "link",\n        lambda *_args, **_kwargs: (_ for _ in ()).throw(OSError(errno.EXDEV, "cross-device")),\n    )\n    restored, stats = cache.restore(entry, tmp_path / "task-work")\n    assert stats["hardlinked_images"] == 0\n    assert stats["copied_images"] == 2\n    assert (restored / "dataset/images/test/img-2.jpg").read_bytes() == b"test-image-bytes"\n\n\ndef test_cache_publish_requires_final_verified_file_count(tmp_path):\n    snapshot_id = "d" * 64\n    source_bundle = _write_bundle(tmp_path / "source", snapshot_id=snapshot_id)\n    cache = TrainingBundleCache(tmp_path / "data", "project-d")\n\n    with pytest.raises(ValueError, match="file count"):\n        cache.publish_verified(source_bundle, snapshot_id, verified_files=1)\n    assert cache.resolve(snapshot_id) is None\n\n\ndef test_cache_is_project_scoped(tmp_path):\n    snapshot_id = "e" * 64\n    source_bundle = _write_bundle(tmp_path / "source", snapshot_id=snapshot_id)\n    left = TrainingBundleCache(tmp_path / "data", "project-left")\n    right = TrainingBundleCache(tmp_path / "data", "project-right")\n\n    left.publish_verified(source_bundle, snapshot_id, verified_files=2)\n    assert left.resolve(snapshot_id) is not None\n    assert right.resolve(snapshot_id) is None\n\ndef test_indexed_cache_lookup_requires_locked_hash_and_size():\n    from platform_core.training_tasks import _indexed_content_identity_ready\n\n    assert _indexed_content_identity_ready(\n        [{"content_sha256": "f" * 64, "size_bytes": 123}]\n    )\n    assert not _indexed_content_identity_ready(\n        [{"content_sha256": "", "size_bytes": 123}]\n    )\n    assert not _indexed_content_identity_ready(\n        [{"content_sha256": "f" * 64, "size_bytes": 0}]\n    )\n', encoding="utf-8")

training = Path("platform_core/training_tasks.py")
replace_once(training, 'from .training_metrics import read_metrics\n', 'from .training_metrics import read_metrics\nfrom .training_bundle_cache import TrainingBundleCache\n', "training import")
